    default:
      return [:]
    }
  }

  func getSingleton<T>(for type: T.Type) -> T? {
    switch type {
    case is Settings.Type:
      return settings as? T
    default:
      return nil
    }
  }
}

/// All translations for the entry, identified by IETF language tag (BCP47).
public struct LocaleMap<T: Decodable & Equatable & Sendable>: Decodable, Equatable, Sendable {

  public let map: [Locale.ID: T]

  public init(from decoder: Decoder) throws {
    let container = try decoder.singleValueContainer()
    self.map = try container.decode([Locale.ID: T].self)
  }

  public init(_ map: [Locale.ID: T]) {
    self.map = map
  }
}

public protocol Entity: Identifiable, Sendable {

  static var name: String { get }

  static var namePlural: String { get }
}

public protocol LocaleEntity: Entity where ID == String {}

public protocol GeneralEntity: Entity where ID == UUID {}

public protocol ChildEntity: Entity {

  associatedtype ParentID: Equatable & Sendable

  static var parentId: KeyPath<Self, ParentID> & Sendable { get }
}

extension InlineArray: @retroactive Decodable where Element: Decodable {

  public init(from decoder: Decoder) throws {
    var container = try decoder.unkeyedContainer()
    var elements: [Element] = []
    while !container.isAtEnd {
      let element = try container.decode(Element.self)
      elements.append(element)
    }
    self.init { elements[$0] }
  }
}

extension InlineArray: @retroactive Equatable where Element: Equatable {

  public static func == (lhs: InlineArray<count, Element>, rhs: InlineArray<count, Element>) -> Bool {
    guard lhs.count == rhs.count else { return false }
    for i in 0..<lhs.count {
      if lhs[i] != rhs[i] {
        return false
      }
    }
    return true
  }
}

