    let container = try decoder.container(keyedBy: CodingKeys.self)

    let databaseInstanceIdKey = CodingUserInfoKey.databaseInstanceIdKey
    let explicitId = if let databaseInstanceIdKey {
      decoder.userInfo[databaseInstanceIdKey] as? String
    } else {
      String?.none
    }
    let derivedId = decoder.codingPath.last?.stringValue

    guard let id = explicitId ?? derivedId else {
      throw DatabaseInstanceIdDecodingError.missingIdentifierString
    }
    guard let uuid = UUID(uuidString: id) else {
      throw DatabaseInstanceIdDecodingError.invalidUUID
    }

    self.id = uuid
    self.levels = try container.decodeIfPresent(Int.self, forKey: .levels)
    self.nameBuilderRules = try container.decodeIfPresent(ActivatableNameBuilderRules.self, forKey: .nameBuilderRules)
    self.usageType = try container.decode(CombatSpecialAbilityUsageType.self, forKey: .usageType)
    self.type = try container.decode(CombatSpecialAbilityType.self, forKey: .type)
    self.selectOptions = try container.decodeIfPresent(SelectOptions.self, forKey: .selectOptions)
    self.maximum = try container.decodeIfPresent(Int.self, forKey: .maximum)
    self.penalty = try container.decodeIfPresent(Penalty.self, forKey: .penalty)
    self.prerequisites = try container.decodeIfPresent(GeneralPrerequisites.self, forKey: .prerequisites)
    self.combatTechniques = try container.decode(ApplicableCombatTechniques.self, forKey: .combatTechniques)
    self.apValue = try container.decode(AdventurePointsValue.self, forKey: .apValue)
    self.src = try container.decode(PublicationRefs.self, forKey: .src)
    self.translations = try container.decode(LocaleMap<AdvancedCombatSpecialAbilityTranslation>.self, forKey: .translations)
  }

  public init(id: ID, levels: Int? = nil, nameBuilderRules: ActivatableNameBuilderRules? = nil, usageType: CombatSpecialAbilityUsageType, type: CombatSpecialAbilityType, selectOptions: SelectOptions? = nil, maximum: Int? = nil, penalty: Penalty? = nil, prerequisites: GeneralPrerequisites? = nil, combatTechniques: ApplicableCombatTechniques, apValue: AdventurePointsValue, src: PublicationRefs, translations: LocaleMap<AdvancedCombatSpecialAbilityTranslation>) {
      self.id = id
      self.levels = levels
      self.nameBuilderRules = nameBuilderRules
      self.usageType = usageType
      self.type = type
      self.selectOptions = selectOptions
      self.maximum = maximum
      self.penalty = penalty
      self.prerequisites = prerequisites
      self.combatTechniques = combatTechniques
      self.apValue = apValue
      self.src = src
