public enum AdvantageDisadvantageSubtype: Decodable, Equatable, Sendable {

  case magicalRank

  case magicalTitle

  case magicalHonor

  case magicalPunishment

  case blessedRank

  case blessedTitle

  case blessedHonor

  case blessedPunishment

  private enum CodingKeys: String, CodingKey {
    case tag = "kind"
    case magicalRank = "MagicalRank"
    case magicalTitle = "MagicalTitle"
    case magicalHonor = "MagicalHonor"
    case magicalPunishment = "MagicalPunishment"
    case blessedRank = "BlessedRank"
    case blessedTitle = "BlessedTitle"
    case blessedHonor = "BlessedHonor"
    case blessedPunishment = "BlessedPunishment"
  }

  private enum Discriminator: String, Decodable {
    case magicalRank = "MagicalRank"
    case magicalTitle = "MagicalTitle"
    case magicalHonor = "MagicalHonor"
    case magicalPunishment = "MagicalPunishment"
    case blessedRank = "BlessedRank"
    case blessedTitle = "BlessedTitle"
    case blessedHonor = "BlessedHonor"
    case blessedPunishment = "BlessedPunishment"
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    let tag = try container.decode(Discriminator.self, forKey: .tag)
    switch tag {
    case .magicalRank:
      self = .magicalRank
    case .magicalTitle:
      self = .magicalTitle
    case .magicalHonor:
      self = .magicalHonor
    case .magicalPunishment:
      self = .magicalPunishment
    case .blessedRank:
      self = .blessedRank
    case .blessedTitle:
      self = .blessedTitle
    case .blessedHonor:
      self = .blessedHonor
    case .blessedPunishment:
      self = .blessedPunishment
    }
  }
}

