public struct Race: Decodable, Equatable, Sendable, Identifiable, GeneralEntity, ReferencingPublications, NameableTranslatable {

  /// The name of the entity in the database schema.
  public static let name = "Race"

  /// The plural name of the entity in the database schema.
  public static let namePlural = "Races"

  public typealias ID = UUID

  public let id: ID

  /// How many Adventure Points does the race cost during character creation?
  public let apValue: Int

  /// The race’s base values.
  public let baseValues: BaseValues

  /// How many different hair colors a race may have. By default, they have a single one that is for their whole body, but a race may have multiple if their hair color is different for different body parts. Additionally, if the hair color is labelled differently (e.g. scale color), there might be multiple colors for different body parts as well. This should only be set if the hair color count is higher than 1.
  public let hairColorCount: Int?

  /// Configuration for random weight generation.
  public let weight: RandomWeightGeneration

  /// Defines the starting ages for the race. It depends on the selected experience level.
  public let startingAge: [ExperienceLevel.ID: StartingAgeConfigForExperienceLevel]?

  /// References to where in which publications this entry has been defined. Entries may also be added or removed in later printings.
  public let src: PublicationRefs

  /// All translations for the entry, identified by IETF language tag (BCP47).
  public let translations: LocaleMap<RaceTranslation>

  private enum CodingKeys: String, CodingKey {
    case apValue = "ap_value"
    case baseValues = "base_values"
    case hairColorCount = "hairColorCount"
    case weight = "weight"
    case startingAge = "starting_age"
    case src = "src"
    case translations = "translations"
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)

    let databaseInstanceIdKey = CodingUserInfoKey.databaseInstanceIdKey
    let explicitId = if let databaseInstanceIdKey {
      decoder.userInfo[databaseInstanceIdKey] as? String
    } else {
      String?.none
    }
    let derivedId = decoder.codingPath.last?.stringValue

    guard let id = explicitId ?? derivedId else {
      throw DatabaseInstanceIdDecodingError.missingIdentifierString
    }
    guard let uuid = UUID(uuidString: id) else {
      throw DatabaseInstanceIdDecodingError.invalidUUID
    }

    self.id = uuid
    self.apValue = try container.decode(Int.self, forKey: .apValue)
    self.baseValues = try container.decode(BaseValues.self, forKey: .baseValues)
    self.hairColorCount = try container.decodeIfPresent(Int.self, forKey: .hairColorCount)
    self.weight = try container.decode(RandomWeightGeneration.self, forKey: .weight)
    self.startingAge = try container.decodeIfPresent([ExperienceLevel.ID: StartingAgeConfigForExperienceLevel].self, forKey: .startingAge)
    self.src = try container.decode(PublicationRefs.self, forKey: .src)
    self.translations = try container.decode(LocaleMap<RaceTranslation>.self, forKey: .translations)
  }

  public init(id: ID, apValue: Int, baseValues: BaseValues, hairColorCount: Int? = nil, weight: RandomWeightGeneration, startingAge: [ExperienceLevel.ID: StartingAgeConfigForExperienceLevel]? = nil, src: PublicationRefs, translations: LocaleMap<RaceTranslation>) {
      self.id = id
      self.apValue = apValue
      self.baseValues = baseValues
      self.hairColorCount = hairColorCount
      self.weight = weight
      self.startingAge = startingAge
      self.src = src
      self.translations = translations
  }
}

