public struct Cantrip: Decodable, Equatable, Sendable, Identifiable, GeneralEntity, ReferencingPublications, NameableTranslatable {

  /// The name of the entity in the database schema.
  public static let name = "Cantrip"

  /// The plural name of the entity in the database schema.
  public static let namePlural = "Cantrips"

  public typealias ID = UUID

  public let id: ID

  /// Measurable parameters of a cantrip.
  public let parameters: CantripPerformanceParameters

  /// The target category – the kind of creature or object – the skill affects.
  public let target: AffectedTargetCategories

  /// The associated property.
  public let property: Property.ID

  /// A note specifying the dissemination of the cantrip in different traditions. Sometimes a cantrip is exclusively available to one or more specific traditions, but usually one the academies and traditions are listed the cantrip is most commonly teached in.
  public let note: CantripNote?

  /// References to where in which publications this entry has been defined. Entries may also be added or removed in later printings.
  public let src: PublicationRefs

  /// All translations for the entry, identified by IETF language tag (BCP47).
  public let translations: LocaleMap<CantripTranslation>

  private enum CodingKeys: String, CodingKey {
    case parameters = "parameters"
    case target = "target"
    case property = "property"
    case note = "note"
    case src = "src"
    case translations = "translations"
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)

    let databaseInstanceIdKey = CodingUserInfoKey.databaseInstanceIdKey
    let explicitId = if let databaseInstanceIdKey {
      decoder.userInfo[databaseInstanceIdKey] as? String
    } else {
      String?.none
    }
    let derivedId = decoder.codingPath.last?.stringValue

    guard let id = explicitId ?? derivedId else {
      throw DatabaseInstanceIdDecodingError.missingIdentifierString
    }
    guard let uuid = UUID(uuidString: id) else {
      throw DatabaseInstanceIdDecodingError.invalidUUID
    }

    self.id = uuid
    self.parameters = try container.decode(CantripPerformanceParameters.self, forKey: .parameters)
    self.target = try container.decode(AffectedTargetCategories.self, forKey: .target)
    self.property = try container.decode(Property.ID.self, forKey: .property)
    self.note = try container.decodeIfPresent(CantripNote.self, forKey: .note)
    self.src = try container.decode(PublicationRefs.self, forKey: .src)
    self.translations = try container.decode(LocaleMap<CantripTranslation>.self, forKey: .translations)
  }

  public init(id: ID, parameters: CantripPerformanceParameters, target: AffectedTargetCategories, property: Property.ID, note: CantripNote? = nil, src: PublicationRefs, translations: LocaleMap<CantripTranslation>) {
      self.id = id
      self.parameters = parameters
      self.target = target
      self.property = property
      self.note = note
      self.src = src
      self.translations = translations
  }
}

