    let container = try decoder.container(keyedBy: CodingKeys.self)
    let tag = try container.decode(Discriminator.self, forKey: .tag)
    switch tag {
    case .identifier:
      self = .identifier(try container.decode(RequirableSelectOptionIdentifier.self, forKey: .identifier))
    case .text:
      self = .text(try container.decode(ProfessionSpecialAbilityTextOption.self, forKey: .text))
    case .select:
      self = .select
    }
  }
}

