/// A personality trait describes character aspects of a person from a certain region. Higher trait levels only cover a part of the region covered by lower-level traits.
public struct PersonalityTrait: Decodable, Equatable, Sendable, Identifiable, GeneralEntity, ReferencingPublications, NameableTranslatable {

  /// The name of the entity in the database schema.
  public static let name = "PersonalityTrait"

  /// The plural name of the entity in the database schema.
  public static let namePlural = "PersonalityTraits"

  public typealias ID = UUID

  public let id: ID

  /// The personality trait’s level.
  public let level: Int

  public let prerequisites: PersonalityTraitPrerequisites?

  /// The lower-level personality trait(s) this trait can be combined with.
  public let combinationOptions: [PersonalityTrait.ID]?

  /// References to where in which publications this entry has been defined. Entries may also be added or removed in later printings.
  public let src: PublicationRefs

  /// All translations for the entry, identified by IETF language tag (BCP47).
  public let translations: LocaleMap<PersonalityTraitTranslation>

  private enum CodingKeys: String, CodingKey {
    case level = "level"
    case prerequisites = "prerequisites"
    case combinationOptions = "combination_options"
    case src = "src"
    case translations = "translations"
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)

    let databaseInstanceIdKey = CodingUserInfoKey.databaseInstanceIdKey
    let explicitId = if let databaseInstanceIdKey {
      decoder.userInfo[databaseInstanceIdKey] as? String
    } else {
      String?.none
    }
    let derivedId = decoder.codingPath.last?.stringValue

    guard let id = explicitId ?? derivedId else {
      throw DatabaseInstanceIdDecodingError.missingIdentifierString
    }
    guard let uuid = UUID(uuidString: id) else {
      throw DatabaseInstanceIdDecodingError.invalidUUID
    }

    self.id = uuid
    self.level = try container.decode(Int.self, forKey: .level)
    self.prerequisites = try container.decodeIfPresent(PersonalityTraitPrerequisites.self, forKey: .prerequisites)
    self.combinationOptions = try container.decodeIfPresent([PersonalityTrait.ID].self, forKey: .combinationOptions)
    self.src = try container.decode(PublicationRefs.self, forKey: .src)
    self.translations = try container.decode(LocaleMap<PersonalityTraitTranslation>.self, forKey: .translations)
  }

  public init(id: ID, level: Int, prerequisites: PersonalityTraitPrerequisites? = nil, combinationOptions: [PersonalityTrait.ID]? = nil, src: PublicationRefs, translations: LocaleMap<PersonalityTraitTranslation>) {
      self.id = id
      self.level = level
      self.prerequisites = prerequisites
      self.combinationOptions = combinationOptions
      self.src = src
      self.translations = translations
  }
}

