    guard let uuid = UUID(uuidString: id) else {
      throw DatabaseInstanceIdDecodingError.invalidUUID
    }

    self.id = uuid
    self.playerTypes = try container.decode([PlayerType.ID].self, forKey: .playerTypes)
    self.isMissingImplementation = try container.decode(Bool.self, forKey: .isMissingImplementation)
    self.src = try container.decode(PublicationRefs.self, forKey: .src)
    self.translations = try container.decode(LocaleMap<AlternativeRuleTranslation>.self, forKey: .translations)
  }

  public init(id: ID, playerTypes: [PlayerType.ID], isMissingImplementation: Bool, src: PublicationRefs, translations: LocaleMap<AlternativeRuleTranslation>) {
      self.id = id
      self.playerTypes = playerTypes
      self.isMissingImplementation = isMissingImplementation
      self.src = src
      self.translations = translations
  }
}

