    guard let uuid = UUID(uuidString: id) else {
      throw DatabaseInstanceIdDecodingError.invalidUUID
    }

    self.id = uuid
    self.src = try container.decode(PublicationRefs.self, forKey: .src)
    self.translations = try container.decode(LocaleMap<SexPracticeTranslation>.self, forKey: .translations)
  }

  public init(id: ID, src: PublicationRefs, translations: LocaleMap<SexPracticeTranslation>) {
      self.id = id
      self.src = src
      self.translations = translations
  }
}

